return {api_version=1,id="EX1_057",name="Ancient Brewmaster",text="<b>Battlecry:</b> Return a friendly minion from the battlefield to your hand.",set="EXPERT1",type="minion",rarity="common",cost=4,attack=5,health=4,keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx,self)local r={};for _,e in ipairs(ctx:friendly_minions(self))do if e~=self then r[#r+1]=e end end;return r end,on_battlecry=function(ctx,self,target)if target then ctx:move_to_hand(ctx:controller(self),target)end end}
